using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values inline.
        // DateTime.UtcNow in seed data was always problematic; use a fixed value.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<CosmosDocument> Documents => Set<CosmosDocument>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "SampleDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<CosmosDocument>(b =>
        {
            b.ToContainer("Documents");
            b.HasPartitionKey(d => d.PartitionKey);

            // Breaking change 1: EF Core 9 renamed the default discriminator property
            // from "Discriminator" to "$type". Existing documents use "Discriminator",
            // so we must explicitly configure it to keep reading old data.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class CosmosDocument
{
    public string Id { get; set; } = null!;
    public string PartitionKey { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// Breaking change 2: Synchronous I/O on Cosmos DB is no longer supported in EF Core 9.
// All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 - synchronous, now throws InvalidOperationException):
    //   var docs = _db.Documents.ToList();
    //   var doc  = _db.Documents.First(d => d.Id == id);

    // AFTER (EF Core 9 - async only):
    public async Task<List<CosmosDocument>> GetAllAsync()
        => await _db.Documents.ToListAsync();

    public async Task<CosmosDocument?> GetByIdAsync(string id)
        => await _db.Documents.FirstOrDefaultAsync(d => d.Id == id);
}

